    formatDate(date, format = 'YYYY-MM-DD HH:mm:ss') {
        const d = new Date(date);
        const pad = (n) => String(n).padStart(2, '0');
        const map = {
            'YYYY': d.getFullYear(),
            'MM': pad(d.getMonth() + 1),
            'DD': pad(d.getDate()),
            'HH': pad(d.getHours()),
            'mm': pad(d.getMinutes()),
            'ss': pad(d.getSeconds())
        };
        let result = format;
        for (const [key, val] of Object.entries(map)) {
            result = result.replace(key, val);
        }
        return result;
    },

