/**
 * API 客户端 — 封装后端 HTTP 请求
 *
 * 提供 sendChat（非流式）、sendChatStream（SSE 流式）、
 * fetchProjects、healthCheck 四个接口方法
 * 开发环境通过 Vite 代理转发，生产环境直连 Cloudflare Worker
 */
import type { Project } from '../types'
import { normalizeApiBase } from './apiBase'

/** API 基础 URL —— 生产环境指向 Cloudflare Worker，开发环境指向本地代理 */
const API_BASE = normalizeApiBase(import.meta.env.VITE_API_BASE)

/** 构建 API URL，调用方统一传入以 / 开头的路由。 */
export function apiUrl(path: string): string {
  return `${API_BASE}${path.startsWith('/') ? path : `/${path}`}`
}

async function request<T>(path: string, options?: RequestInit): Promise<T> {
  const res = await fetch(apiUrl(path), {
    headers: {
      'Content-Type': 'application/json',
    },
    ...options,
  })

  if (!res.ok) {
    const body = await res.text()
    throw new Error(`API Error ${res.status}: ${body}`)
  }

  return res.json() as Promise<T>
}

/** 获取项目列表 */
export async function fetchProjects(): Promise<Project[]> {
  return request('/projects')
}

/** 检查服务状态 */
export async function healthCheck(): Promise<{ ok: boolean; lastIndexedAt: string | null }> {
  return request('/health')
}

}

/** 检查服务状态 */
export async function healthCheck(): Promise<{ ok: boolean; lastIndexedAt: string | null }> {
  return request('/health')
}

/** Normalize the configured Worker URL to the API route prefix. */
export function normalizeApiBase(value: string | undefined): string {
  const configured = value?.trim() || '/api'
  const base = configured.replace(/\/+$/, '')

  return base.endsWith('/api') ? base : `${base}/api`
}

import type { ChatEvent } from '../types'

/**
 * SSE 流解析器
 *
 * 用法：
 * ```ts
 * const response = await fetch(url, { body, headers })
 * const reader = response.body!.getReader()
 * for await (const event of parseSSEStream(reader)) {
 *   // 处理每个 ChatEvent
 * }
 * ```
 */
export async function* parseSSEStream(
  reader: ReadableStreamDefaultReader<Uint8Array>,
): AsyncGenerator<ChatEvent> {
  const decoder = new TextDecoder()
  let buffer = ''

  while (true) {
    const { done, value } = await reader.read()

    if (done) break

    buffer += decoder.decode(value, { stream: true })

    // SSE 使用双换行分隔事件
    const parts = buffer.split(/\r?\n\r?\n/)
    // 最后一个可能不完整，保留到下次循环
    buffer = parts.pop() ?? ''

    for (const part of parts) {
      const lines = part.split(/\r?\n/)
      for (const line of lines) {
        if (line.startsWith('data: ')) {
          const data = line.slice(6).trim()
          if (data === '[DONE]') {
            yield { type: 'done' }
            return
          }
          try {
            const event = JSON.parse(data) as ChatEvent
            yield event
          } catch {
            // 跳过无法解析的行
            continue
          }
        }
      }
    }
  }

yield event
          } catch {
            // 跳过无法解析的行
            continue
          }
        }
      }
    }
  }

  // 处理残留的 buffer
  if (buffer.trim()) {
    const lines = buffer.split(/\r?\n/)
    for (const line of lines) {
      if (line.startsWith('data: ')) {
        const data = line.slice(6).trim()
        if (data === '[DONE]') {
          yield { type: 'done' }
          return
        }
        try {
          const event = JSON.parse(data) as ChatEvent
          yield event
        } catch {
          continue
        }
      }
    }
  }
}

