async function fetchGitHubRepositories(account, existingSelection = null) {
  const username = normalizeGitHubUsername(account);
  if (!username) throw new Error('请输入有效的 GitHub 用户名或个人主页地址');
  const repositories = [];
  for (let page = 1; page <= 3; page += 1) {
    const batch = await githubRequest(`/users/${encodeURIComponent(username)}/repos?type=owner&sort=updated&direction=desc&per_page=100&page=${page}`);
    if (!Array.isArray(batch)) throw new Error('GitHub 返回的仓库列表格式异常');
    repositories.push(...batch);
    if (batch.length < 100) break;
  }
  const prepared = prepareGitHubRepositories(repositories, username, existingSelection);
  if (!prepared.repositories.length) throw new Error('该账号没有可用于生成项目经历的公开自有仓库');
  return { username, ...prepared };
}

