async function githubRequest(path, { allowNotFound = false, timeoutMs = 20000 } = {}) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    const response = await fetch(`${GITHUB_API_BASE}${path}`, {
      headers: {
        Accept: 'application/vnd.github+json',
        'X-GitHub-Api-Version': '2022-11-28'
      },
      cache: 'no-store',
      credentials: 'omit',
      signal: controller.signal
    });
    if (allowNotFound && response.status === 404) return null;
    const payload = await response.json().catch(() => null);
    if (!response.ok) {
      const remaining = response.headers?.get?.('x-ratelimit-remaining');
      if (response.status === 403 && remaining === '0') {
        throw new Error('GitHub 公共接口请求次数已用完，请稍后再试');
      }
      if (response.status === 404) throw new Error('没有找到该 GitHub 用户或仓库');
      throw new Error(payload?.message ? `GitHub：${payload.message}` : `GitHub 请求失败 HTTP ${response.status}`);
    }
    return payload;
  } catch (error) {
    if (error?.name === 'AbortError') throw new Error('GitHub 请求超时，请检查网络后重试');
    throw error;
  } finally {
    clearTimeout(timer);
  }
}

if (error?.name === 'AbortError') throw new Error('GitHub 请求超时，请检查网络后重试');
