function repositoryScore(repository) {
  const pushed = Date.parse(repository.pushedAt || '') || 0;
  const ageDays = pushed ? Math.max(0, (Date.now() - pushed) / 86400000) : 3650;
  const freshness = Math.max(0, 42 - Math.log2(ageDays + 2) * 6);
  return (repository.description ? 22 : 0)
    + (repository.homepage ? 8 : 0)
    + Math.min(18, repository.languages.length * 4)
    + Math.min(12, repository.topics.length * 2)
    + Math.min(18, Math.log2(repository.stars + 1) * 4)
    + Math.min(8, Math.log2(repository.forks + 1) * 3)
    + freshness
    + (repository.size > 0 ? 5 : -15)
    - (repository.archived ? 45 : 0);
}

+ Math.min(8, Math.log2(repository.forks + 1) * 3)
    + freshness
    + (repository.size > 0 ? 5 : -15)
    - (repository.archived ? 45 : 0);
}

export function normalizeGitHubUsername(value) {
  let candidate = String(value || '').trim();
  if (!candidate) return '';
  candidate = candidate.replace(/^@/, '');
  try {
    const url = new URL(candidate.includes('://') ? candidate : `https://${candidate}`);
    if (url.hostname.toLowerCase() === 'github.com' || url.hostname.toLowerCase() === 'www.github.com') {
      candidate = url.pathname.split('/').filter(Boolean)[0] || '';
    }
  } catch {
    candidate = candidate.replace(/^https?:\/\/(?:www\.)?github\.com\//i, '').split(/[/?#]/)[0];
  }
  candidate = candidate.trim();
  if (!/^[A-Za-z0-9](?:[A-Za-z0-9-]{0,37}[A-Za-z0-9])?$/.test(candidate)) return '';
  if (candidate.includes('--')) return '';
  return candidate;
}

if (candidate.includes('--')) return '';
  return candidate;
}

export function prepareGitHubRepositories(rawRepositories, username = '', existingSelection = null) {
  const hasExplicitSelection = Array.isArray(existingSelection);
  const selected = new Set(unique(existingSelection, MAX_PROJECTS).map(value => value.toLowerCase()));
  const repositories = (Array.isArray(rawRepositories) ? rawRepositories : [])
    .map(raw => normalizeRepository(raw, username))
    .filter(repository => repository.name && repository.fullName && repository.url)
    .filter(repository => !repository.private && !repository.fork && !repository.disabled)
    .sort((left, right) => repositoryScore(right) - repositoryScore(left)
      || Date.parse(right.pushedAt || '') - Date.parse(left.pushedAt || '')
      || left.name.localeCompare(right.name, 'en'))
    .slice(0, MAX_REPOSITORIES);

  const selectable = repositories.filter(repository => !repository.archived && repository.size > 0);
  const defaults = new Set((hasExplicitSelection
    ? repositories.filter(repository => selected.has(repository.fullName.toLowerCase()))
    : selectable.slice(0, 3)).map(repository => repository.fullName));
  return {
    repositories,
    selectedRepositories: [...defaults].slice(0, MAX_PROJECTS)
  };
}

