async function persistResumeBuilderDraftNow({ notify = true } = {}) {
  clearTimeout(resumeBuilderSaveTimer);
  resumeBuilderSaveTimer = null;
  const draft = collectResumeBuilderDraft();
  resumeBuilderDraft = draft;
  if (!resumeBuilderDirty) return draft;
  const revision = resumeBuilderRevision;
  const result = await send('SAVE_RESUME_BUILDER', { draft });
  if (!result.ok) {
    if (notify) showToast(result.error || '简历草稿保存失败', true);
    return draft;
  }
  state.resumeBuilderDraft = result.draft;
  if (revision === resumeBuilderRevision) {
    resumeBuilderDraft = result.draft;
    resumeBuilderDirty = false;
    renderResumeBuilderStatus();
  }
  return result.draft;
}

function scheduleResumeBuilderDraftSave() {
  clearTimeout(resumeBuilderSaveTimer);
  resumeBuilderSaveTimer = setTimeout(() => persistResumeBuilderDraftNow(), 240);
