     * @param authorizationHeader Bearer Token
     * @return 会员信息
     */
    @GetMapping("/verify")
    public R<MemberResponseVo> verify(@RequestHeader(value = "Authorization", required = false) String authorizationHeader) {
        if (authorizationHeader == null || !authorizationHeader.startsWith("Bearer ")) {
            return R.error(BizCode.TOKEN_INVALID);
        }

        String token = authorizationHeader.substring(7);

        // 校验 Token
        if (!jwtTokenProvider.validateToken(token)) {
            return R.error(BizCode.TOKEN_EXPIRED);
        }

        // 提取会员信息
        Long memberId = jwtTokenProvider.getMemberIdFromToken(token);
        String username = jwtTokenProvider.getUsernameFromToken(token);

        MemberResponseVo member = new MemberResponseVo();
        member.setId(memberId);
        member.setUsername(username);

        log.info("Token 验证成功: memberId={}, username={}", memberId, username);
        return R.ok(member);
    }
