package com.atguigu.gulimall.auth.service;

import com.atguigu.gulimall.auth.feign.ThirdPartyFeignService;
import com.atguigu.gulimall.common.exception.GulimallException;
import com.atguigu.gulimall.common.utils.BizCode;
import com.atguigu.gulimall.common.utils.R;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.stereotype.Service;

import java.security.SecureRandom;
import java.time.Duration;

@Service
public class SmsCodeService {

    private static final String CODE_PREFIX = "auth:sms:code:";
    private static final String RATE_PREFIX = "auth:sms:rate:";

    private final StringRedisTemplate redisTemplate;
    private final ThirdPartyFeignService thirdPartyFeignService;
    private final boolean devMode;
    private final SecureRandom random = new SecureRandom();

    public SmsCodeService(StringRedisTemplate redisTemplate,
                          ThirdPartyFeignService thirdPartyFeignService,
                          @Value("${sms.dev-mode:false}") boolean devMode) {
        this.redisTemplate = redisTemplate;
        this.thirdPartyFeignService = thirdPartyFeignService;
        this.devMode = devMode;
    }

this.redisTemplate = redisTemplate;
        this.thirdPartyFeignService = thirdPartyFeignService;
        this.devMode = devMode;
    }

    public String send(String phone) {
        if (phone == null || !phone.matches("^1\\d{10}$")) {
            throw new GulimallException(BizCode.PARAM_VALID_EXCEPTION.getCode(), "手机号格式错误");
        }
        Boolean allowed = redisTemplate.opsForValue()
                .setIfAbsent(RATE_PREFIX + phone, "1", Duration.ofSeconds(60));
        if (!Boolean.TRUE.equals(allowed)) {
            throw new GulimallException(BizCode.TOO_MANY_REQUEST.getCode(), "请在 60 秒后重试");
        }
        String code = String.format("%06d", random.nextInt(1_000_000));
        try {
            if (!devMode) {
                R<Void> response = thirdPartyFeignService.sendSms(phone, code);
                if (response == null || response.getCode() != 0) {
                    throw new GulimallException(BizCode.UNKNOWN_EXCEPTION.getCode(),
                            response == null ? "短信服务不可用" : response.getMessage());
                }
            }
            redisTemplate.opsForValue().set(CODE_PREFIX + phone, code, Duration.ofMinutes(5));
            return devMode ? code : null;
        } catch (RuntimeException e) {
            redisTemplate.delete(RATE_PREFIX + phone);
            throw e;
        }
    }

} catch (RuntimeException e) {
            redisTemplate.delete(RATE_PREFIX + phone);
            throw e;
        }
    }

    public boolean verify(String phone, String code) {
        String expected = redisTemplate.opsForValue().get(CODE_PREFIX + phone);
        return expected != null && expected.equals(code);
    }

    public void consume(String phone) {
        redisTemplate.delete(CODE_PREFIX + phone);
    }
}

