package com.atguigu.gulimall.cart.interceptor;

import jakarta.servlet.http.Cookie;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import jakarta.servlet.http.HttpSession;
import org.springframework.stereotype.Component;
import org.springframework.web.servlet.HandlerInterceptor;

import java.util.UUID;

@Component
public class CartInterceptor implements HandlerInterceptor {

    public static final ThreadLocal<String> CART_KEY = new ThreadLocal<>();

    private static final String COOKIE_NAME = "user-key";
    private static final int COOKIE_MAX_AGE = 30 * 24 * 60 * 60;

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response,
                             Object handler) throws Exception {
        String cartKey = null;

        // 先从 session 中获取用户信息
        HttpSession session = request.getSession(false);
        if (session != null && session.getAttribute("userId") != null) {
            cartKey = session.getAttribute("userId").toString();
        }

if (session != null && session.getAttribute("userId") != null) {
            cartKey = session.getAttribute("userId").toString();
        }

        // 未登录用户从 cookie 中获取临时 key
        if (cartKey == null) {
            Cookie[] cookies = request.getCookies();
            if (cookies != null) {
                for (Cookie cookie : cookies) {
                    if (COOKIE_NAME.equals(cookie.getName())) {
                        cartKey = cookie.getValue();
                        break;
                    }
                }
            }
            // 如果没有临时 key，生成一个并写入 cookie
            if (cartKey == null) {
                cartKey = UUID.randomUUID().toString().replace("-", "");
                Cookie cookie = new Cookie(COOKIE_NAME, cartKey);
                cookie.setMaxAge(COOKIE_MAX_AGE);
                cookie.setPath("/");
                response.addCookie(cookie);
            }
        }

        CART_KEY.set(cartKey);
        return true;
    }

    @Override
    public void afterCompletion(HttpServletRequest request, HttpServletResponse response,
                                Object handler, Exception ex) {
        CART_KEY.remove();
    }
}

Object handler, Exception ex) {
        CART_KEY.remove();
    }
}

