    private StringRedisTemplate stringRedisTemplate;

    @Resource
    private ProductFeignService productFeignService;

    @Override
    public Cart getCart() {
        String cartKey = getCartKey();
        BoundHashOperations<String, Object, Object> hashOps =
                stringRedisTemplate.boundHashOps(CART_PREFIX + cartKey);

BoundHashOperations<String, Object, Object> hashOps =
                stringRedisTemplate.boundHashOps(CART_PREFIX + cartKey);

        Map<Object, Object> entries = hashOps.entries();
        List<CartItem> items = entries.values().stream()
                .map(obj -> JSONUtil.toBean(obj.toString(), CartItem.class))
                .collect(Collectors.toList());

        Cart cart = new Cart();
        cart.setItems(items);

        int totalCount = 0;
        BigDecimal totalAmount = BigDecimal.ZERO;
        for (CartItem item : items) {
            if (Boolean.TRUE.equals(item.getCheck())) {
                totalCount += item.getCount();
                totalAmount = totalAmount.add(item.getTotalPrice());
            }
        }
        cart.setTotalCount(totalCount);
        cart.setTotalAmount(totalAmount);

        return cart;
    }

    @Override
    public CartItem addToCart(Long skuId, Integer num) {
        validateCount(num);
        String cartKey = getCartKey();
        BoundHashOperations<String, Object, Object> hashOps =
                stringRedisTemplate.boundHashOps(CART_PREFIX + cartKey);
        String skuIdStr = skuId.toString();

stringRedisTemplate.boundHashOps(CART_PREFIX + cartKey);
        String skuIdStr = skuId.toString();

        // 检查购物车中是否已存在该商品
        Object existing = hashOps.get(skuIdStr);
        CartItem cartItem;
        if (existing != null) {
            cartItem = JSONUtil.toBean(existing.toString(), CartItem.class);
            int updatedCount = cartItem.getCount() + num;
            validateCount(updatedCount);
            cartItem.setCount(updatedCount);
            cartItem.setTotalPrice(cartItem.getPrice().multiply(new BigDecimal(cartItem.getCount())));
        } else {
            R<SkuInfoTo> response = productFeignService.getSkuForCart(skuId);
            if (response == null || response.getCode() != 0 || response.getData() == null) {
                throw new GulimallException(BizCode.PRODUCT_NOT_FOUND);
            }
            SkuInfoTo sku = response.getData();
            cartItem = new CartItem();
            cartItem.setSkuId(skuId);
            cartItem.setCheck(true);
            cartItem.setTitle(StringUtils.hasText(sku.getSkuTitle()) ? sku.getSkuTitle() : sku.getSkuName());
            cartItem.setDefaultImage(sku.getSkuDefaultImg());
            cartItem.setPrice(sku.getPrice());
            cartItem.setSkuAttrValues(sku.getSaleAttrValues());
            cartItem.setCount(num);
            cartItem.setTotalPrice(cartItem.getPrice().multiply(new BigDecimal(num)));
        }

cartItem.setCount(num);
            cartItem.setTotalPrice(cartItem.getPrice().multiply(new BigDecimal(num)));
        }

        hashOps.put(skuIdStr, JSONUtil.toJsonStr(cartItem));
        stringRedisTemplate.expire(CART_PREFIX + cartKey, 30, TimeUnit.DAYS);
        return cartItem;
    }

    @Override
    public CartItem updateItemCount(Long skuId, Integer count) {
        validateCount(count);
        BoundHashOperations<String, Object, Object> hashOps = stringRedisTemplate
                .boundHashOps(CART_PREFIX + getCartKey());
        Object existing = hashOps.get(skuId.toString());
        if (existing == null) {
            throw new GulimallException(BizCode.CART_ITEM_NOT_FOUND);
        }
        CartItem item = JSONUtil.toBean(existing.toString(), CartItem.class);
        item.setCount(count);
        item.setTotalPrice(item.getPrice().multiply(BigDecimal.valueOf(count)));
        hashOps.put(skuId.toString(), JSONUtil.toJsonStr(item));
        return item;
    }

    @Override
    public void checkItem(Long skuId, Boolean checked) {
        String cartKey = getCartKey();
        BoundHashOperations<String, Object, Object> hashOps =
                stringRedisTemplate.boundHashOps(CART_PREFIX + cartKey);
        String skuIdStr = skuId.toString();

        Object existing = hashOps.get(skuIdStr);
        if (existing == null) {
            throw new GulimallException(BizCode.CART_ITEM_NOT_FOUND);
        }

if (existing == null) {
            throw new GulimallException(BizCode.CART_ITEM_NOT_FOUND);
        }

        CartItem cartItem = JSONUtil.toBean(existing.toString(), CartItem.class);
        cartItem.setCheck(checked);
        hashOps.put(skuIdStr, JSONUtil.toJsonStr(cartItem));
    }

    @Override
    public void deleteItem(Long skuId) {
        String cartKey = getCartKey();
        BoundHashOperations<String, Object, Object> hashOps =
                stringRedisTemplate.boundHashOps(CART_PREFIX + cartKey);

        hashOps.delete(skuId.toString());
    }

    /**
     * 获取当前用户的购物车 key
     */
    private String getCartKey() {
        String cartKey = CartInterceptor.CART_KEY.get();
        if (!StringUtils.hasText(cartKey)) {
            throw new GulimallException(BizCode.AUTH_FAIL);
        }
        return cartKey;
    }

    private void validateCount(Integer count) {
        if (count == null || count < 1 || count > 999) {
            throw new GulimallException(BizCode.PARAM_VALID_EXCEPTION.getCode(),
                    "商品数量必须在 1 到 999 之间");
        }
    }
