package com.atguigu.gulimall.common.exception;

import com.atguigu.gulimall.common.utils.BizCode;
import com.atguigu.gulimall.common.utils.R;
import lombok.extern.slf4j.Slf4j;
import org.springframework.http.HttpStatus;
import org.springframework.validation.BindException;
import org.springframework.validation.FieldError;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestControllerAdvice;

import java.util.List;
import java.util.stream.Collectors;

/**
 * 全局异常处理器
 *
 * @author gulimall
 */
@Slf4j
@RestControllerAdvice
public class GulimallExceptionHandler {

    /**
     * 处理参数校验失败异常（@Validated）
     */
    @ExceptionHandler(MethodArgumentNotValidException.class)
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public R<Void> handleValidException(MethodArgumentNotValidException e) {
        List<FieldError> fieldErrors = e.getBindingResult().getFieldErrors();
        String message = fieldErrors.stream()
                .map(err -> err.getField() + ": " + err.getDefaultMessage())
                .collect(Collectors.joining(", "));
        log.warn("参数校验失败: {}", message);
        return R.error(BizCode.PARAM_VALID_EXCEPTION.getCode(), message);
    }

    /**
     * 处理绑定异常（@Valid）
     */
    @ExceptionHandler(BindException.class)
    @ResponseStatus(HttpStatus.BAD_REQUEST)

}

    /**
     * 处理绑定异常（@Valid）
     */
    @ExceptionHandler(BindException.class)
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public R<Void> handleBindException(BindException e) {
        List<FieldError> fieldErrors = e.getBindingResult().getFieldErrors();
        String message = fieldErrors.stream()
                .map(err -> err.getField() + ": " + err.getDefaultMessage())
                .collect(Collectors.joining(", "));
        log.warn("绑定校验失败: {}", message);
        return R.error(BizCode.PARAM_VALID_EXCEPTION.getCode(), message);
    }

    /**
     * 处理自定义业务异常
     */
    @ExceptionHandler(GulimallException.class)
    public R<Void> handleGulimallException(GulimallException e) {
        log.error("业务异常: code={}, message={}", e.getCode(), e.getMessage());
        return R.error(e.getCode(), e.getMessage());
    }

    /**
     * 处理未知异常
     */
    @ExceptionHandler(Exception.class)
    @ResponseStatus(HttpStatus.INTERNAL_SERVER_ERROR)
    public R<Void> handleException(Exception e) {
        log.error("系统未知异常", e);
        return R.error(BizCode.UNKNOWN_EXCEPTION);
    }

    /**
     * 处理限流异常（Sentinel）
     */
    @ExceptionHandler(RuntimeException.class)

return R.error(BizCode.UNKNOWN_EXCEPTION);
    }

    /**
     * 处理限流异常（Sentinel）
     */
    @ExceptionHandler(RuntimeException.class)
    public R<Void> handleRuntimeException(RuntimeException e) {
        if (e.getMessage() != null && e.getMessage().contains("Sentinel")) {
            log.warn("被 Sentinel 限流: {}", e.getMessage());
            return R.error(BizCode.TOO_MANY_REQUEST);
        }
        log.error("运行时异常", e);
        return R.error(BizCode.UNKNOWN_EXCEPTION);
    }
}

