/**
 * 自定义校验注解 — ListValue：校验值必须在指定数组内
 *
 * @author gulimall
 */
@Documented
@Constraint(validatedBy = {ListValueConstraintValidator.class})
@Target({ElementType.METHOD, ElementType.FIELD, ElementType.ANNOTATION_TYPE, ElementType.CONSTRUCTOR, ElementType.PARAMETER, ElementType.TYPE_USE})
@Retention(RetentionPolicy.RUNTIME)
public @interface ListValue {

    String message() default "值不在允许范围内";

    Class<?>[] groups() default {};

    Class<? extends Payload>[] payload() default {};

    /** 允许的值列表 */
    int[] vals() default {};
}

package com.atguigu.gulimall.common.valid;

import jakarta.validation.ConstraintValidator;
import jakarta.validation.ConstraintValidatorContext;
import java.util.HashSet;
import java.util.Set;

/**
 * ListValue 校验器实现
 *
 * @author gulimall
 */
public class ListValueConstraintValidator implements ConstraintValidator<ListValue, Integer> {

    private final Set<Integer> allowedValues = new HashSet<>();

    @Override
    public void initialize(ListValue constraintAnnotation) {
        for (int val : constraintAnnotation.vals()) {
            allowedValues.add(val);
        }
    }

    @Override
    public boolean isValid(Integer value, ConstraintValidatorContext context) {
        if (value == null) {
            return true; // null 不校验，由 @NotNull 处理
        }
        return allowedValues.contains(value);
    }
}

if (value == null) {
            return true; // null 不校验，由 @NotNull 处理
        }
        return allowedValues.contains(value);
    }
}

