@Component
public class JwtAuthenticationFilter implements GlobalFilter, Ordered {

    public static final String MEMBER_ID_HEADER = "X-Member-Id";
    public static final String MEMBER_USERNAME_HEADER = "X-Member-Username";

    private static final List<String> PROTECTED_PATHS = List.of(
            "/api/order/order/submit",
            "/api/order/order/mine",
            "/api/member/address/mine",
            "/api/seckill/kill"
    );

    private final SecretKey secretKey;

    public JwtAuthenticationFilter(@Value("${jwt.secret}") String secret) {
        this.secretKey = Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));
    }

this.secretKey = Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));
    }

    @Override
    public Mono<Void> filter(ServerWebExchange exchange, GatewayFilterChain chain) {
        ServerHttpRequest.Builder request = exchange.getRequest().mutate();
        request.headers(headers -> {
            headers.remove(MEMBER_ID_HEADER);
            headers.remove(MEMBER_USERNAME_HEADER);
        });

        String path = exchange.getRequest().getURI().getPath();
        String authorization = exchange.getRequest().getHeaders().getFirst(HttpHeaders.AUTHORIZATION);
        Claims claims = parseBearerToken(authorization);
        if (claims != null) {
            Object memberId = claims.get("memberId");
            if (memberId instanceof Number number) {
                request.header(MEMBER_ID_HEADER, String.valueOf(number.longValue()));
                String username = claims.getSubject();
                if (username != null) {
                    request.header(MEMBER_USERNAME_HEADER,
                            URLEncoder.encode(username, StandardCharsets.UTF_8));
                }
                return chain.filter(exchange.mutate().request(request.build()).build());
            }
        }

}
                return chain.filter(exchange.mutate().request(request.build()).build());
            }
        }

        if (isProtected(path)) {
            byte[] body = "{\"code\":18002,\"message\":\"Token invalid or expired\"}"
                    .getBytes(StandardCharsets.UTF_8);
            exchange.getResponse().setStatusCode(HttpStatus.UNAUTHORIZED);
            exchange.getResponse().getHeaders().setContentType(MediaType.APPLICATION_JSON);
            return exchange.getResponse().writeWith(Mono.just(
                    exchange.getResponse().bufferFactory().wrap(body)));
        }
        return chain.filter(exchange.mutate().request(request.build()).build());
    }

    private Claims parseBearerToken(String authorization) {
        if (authorization == null || !authorization.startsWith("Bearer ")) {
            return null;
        }
        try {
            return Jwts.parser().verifyWith(secretKey).build()
                    .parseSignedClaims(authorization.substring(7)).getPayload();
        } catch (RuntimeException ignored) {
            return null;
        }
    }

    private boolean isProtected(String path) {
        return PROTECTED_PATHS.stream().anyMatch(
                protectedPath -> path.equals(protectedPath) || path.startsWith(protectedPath + "/"));
    }

