     */
    @PostMapping("/oauth2/login")
    public R oauth2Login(@RequestBody Map<String, String> socialUser) {
        String uid = socialUser.get("uid");
        if (!StringUtils.hasText(uid)) {
            return R.error(BizCode.PARAM_VALID_EXCEPTION);
        }
        String provider = StringUtils.hasText(socialUser.get("provider"))
                ? socialUser.get("provider") : "oauth";
        String oauthUsername = provider + ":" + uid;
        MemberEntity member = memberService.getOne(new LambdaQueryWrapper<MemberEntity>()
                .eq(MemberEntity::getUsername, oauthUsername));
        if (member == null) {
            member = new MemberEntity();
            member.setUsername(oauthUsername);
            member.setNickname(StringUtils.hasText(socialUser.get("name"))
                    ? socialUser.get("name") : oauthUsername);
            member.setHeader(socialUser.get("avatar"));
            member.setPassword(DigestUtils.md5DigestAsHex(
                    UUID.randomUUID().toString().getBytes(StandardCharsets.UTF_8)));
            member.setSourceType(2);
            member.setStatus(1);
            memberService.save(member);
        } else {
            MemberEntity update = new MemberEntity();
            update.setId(member.getId());
            update.setNickname(socialUser.get("name"));
            update.setHeader(socialUser.get("avatar"));

update.setNickname(socialUser.get("name"));
            update.setHeader(socialUser.get("avatar"));
            memberService.updateById(update);
            member.setNickname(update.getNickname());
            member.setHeader(update.getHeader());
        }
        member.setPassword(null);
        return R.ok(member);
    }
}

