    @GetMapping("/stats/today")
    public R todayStats() {
        LocalDate today = LocalDate.now();
        QueryWrapper<OrderEntity> wrapper = new QueryWrapper<OrderEntity>()
                .ge("create_time", today.atStartOfDay())
                .lt("create_time", today.plusDays(1).atStartOfDay());
        java.util.List<OrderEntity> orders = orderService.list(wrapper);
        BigDecimal sales = orders.stream()
                .filter(order -> order.getPayAmount() != null && order.getStatus() != null
                        && order.getStatus() != 4 && order.getStatus() != 5)
                .map(OrderEntity::getPayAmount)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        Map<String, Object> result = new HashMap<>();
        result.put("orders", orders.size());
        result.put("sales", sales);
        return R.ok(result);
    }
