@Service("categoryService")
public class CategoryServiceImpl extends ServiceImpl<CategoryDao, CategoryEntity> implements CategoryService {

    @Override
    public List<CategoryEntity> listWithTree() {
        // 1. 查出所有分类
        List<CategoryEntity> allCategories = baseMapper.selectList(new LambdaQueryWrapper<>());

        // 2. 组装树形结构：过滤出根节点（parentCid == 0），递归设置子节点
        return allCategories.stream()
                .filter(category -> category.getParentCid() == 0)
                .peek(category -> category.setChildren(getChildren(category, allCategories)))
                .collect(Collectors.toList());
    }

    /**
     * 递归查找当前分类的子分类
     */

.collect(Collectors.toList());
    }

    /**
     * 递归查找当前分类的子分类
     */
    private List<CategoryEntity> getChildren(CategoryEntity root, List<CategoryEntity> all) {
        return all.stream()
                .filter(category -> category.getParentCid().equals(root.getCatId()))
                .peek(category -> category.setChildren(getChildren(category, all)))
                .collect(Collectors.toList());
    }
}

