                List<StringTermsBucket> nameBuckets = nameAgg.sterms().buckets().array();
                if (!nameBuckets.isEmpty()) {
                    brandName = nameBuckets.get(0).key().stringValue();
                }
            }

            String brandImg = "";
            Aggregate imgAgg = bucket.aggregations().get("brand_img");
            if (imgAgg != null && imgAgg.isSterms()) {
                List<StringTermsBucket> imgBuckets = imgAgg.sterms().buckets().array();
                if (!imgBuckets.isEmpty()) {
