    private List<SearchResult.AttrVo> extractAttrs(SearchResponse<SkuEsModel> response) {
        Aggregate attrAgg = response.aggregations().get("attr_agg");
        if (attrAgg == null || !attrAgg.isNested()) {
            return Collections.emptyList();
        }

        NestedAggregate nested = attrAgg.nested();
        Aggregate idAgg = nested.aggregations().get("attr_id_agg");
        if (idAgg == null || !idAgg.isLterms()) {
            return Collections.emptyList();
        }

if (idAgg == null || !idAgg.isLterms()) {
