            if (nameAgg != null && nameAgg.isSterms()) {
                List<StringTermsBucket> nameBuckets = nameAgg.sterms().buckets().array();
                if (!nameBuckets.isEmpty()) {
                    attrName = nameBuckets.get(0).key().stringValue();
                }
