                if (skuResponse == null || skuResponse.getCode() != 0 || skuResponse.getData() == null) {
                    log.warn("跳过不存在的秒杀 SKU: {}", relation.getSkuId());
                    continue;
                }
                SkuInfoTo skuInfo = skuResponse.getData();
                SeckillSkuVo sku = new SeckillSkuVo();
                sku.setSessionId(source.getId());
                sku.setSkuId(relation.getSkuId());
                sku.setSkuName(skuInfo.getSkuName());
                sku.setSkuPrice(skuInfo.getPrice());
                sku.setSeckillPrice(relation.getSeckillPrice());
                sku.setSeckillCount(relation.getSeckillCount());
                sku.setSeckillLimit(relation.getSeckillLimit());
                sku.setStartTime(session.getStartTime());
                sku.setEndTime(session.getEndTime());
                sku.setRandomCode(UUID.randomUUID().toString().replace("-", ""));
                skus.add(sku);

sku.setRandomCode(UUID.randomUUID().toString().replace("-", ""));
                skus.add(sku);

                long ttl = Math.max(60, Duration.between(
                        java.time.LocalDateTime.now(), source.getEndTime()).toSeconds());
                String skuKey = SECKILL_SKU_KEY_PREFIX + sku.getSkuId();
                stringRedisTemplate.opsForValue().set(
                        skuKey, JSONUtil.toJsonStr(sku), ttl, TimeUnit.SECONDS);
                String stockKey = SECKILL_STOCK_KEY_PREFIX + source.getId() + "_" + sku.getSkuId();
                stringRedisTemplate.opsForValue().setIfAbsent(
                        stockKey, String.valueOf(sku.getSeckillCount()), ttl, TimeUnit.SECONDS);
            }
            session.setSeckillSkus(skus);
            sessions.add(session);
        }
        stringRedisTemplate.opsForValue().set(
                SECKILL_SESSIONS_KEY, JSONUtil.toJsonStr(sessions), 3, TimeUnit.DAYS);

        log.info("秒杀数据预加载完成");
    }
}

