        }

        List<SeckillSessionWithSkus> sessions =
                JSONUtil.toList(sessionsJson, SeckillSessionWithSkus.class);

        // 过滤当前时间有效的场次
        Date now = new Date();
        return sessions.stream()
                .filter(s -> s.getStartTime().before(now) && s.getEndTime().after(now))
