        // 解析 killId 获取 sessionId 和 skuId
        String[] parts = killId.split("_");
        if (parts.length != 2) {
            throw new GulimallException(10001, "秒杀参数错误");
        }
        Long skuId = Long.parseLong(parts[1]);
        Long sessionId = Long.parseLong(parts[0]);

        // 1. 校验随机码
        SeckillSkuVo skuVo = getSeckillSkuInfo(skuId);
        if (skuVo.getRandomCode() == null || !skuVo.getRandomCode().equals(key)) {
            throw new GulimallException(10001, "秒杀商品不存在或已结束");
        }
        if (!sessionId.equals(skuVo.getSessionId())) {
            throw new GulimallException(BizCode.PARAM_VALID_EXCEPTION);
        }
        if (skuVo.getSeckillLimit() != null && num > skuVo.getSeckillLimit()) {
            throw new GulimallException(BizCode.PARAM_VALID_EXCEPTION.getCode(),
                    "购买数量超过本场限购数量");
        }

        // 2. 校验秒杀时间
        Date now = new Date();
        if (now.before(skuVo.getStartTime()) || now.after(skuVo.getEndTime())) {
            throw new GulimallException(BizCode.SECKILL_OVER);
        }

throw new GulimallException(BizCode.SECKILL_OVER);
        }

        String userId = memberId.toString();

        // 4. 防重复秒杀
        RLock lock = redissonClient.getLock(SECKILL_LOCK_PREFIX + userId + ":" + killId);
        try {
            if (lock.tryLock(5, 10, TimeUnit.SECONDS)) {
                try {
                    // 检查是否已秒杀
                    String userKey = SECKILL_USER_PREFIX + killId + ":" + userId;
                    if (Boolean.TRUE.equals(stringRedisTemplate.hasKey(userKey))) {
                        throw new GulimallException(BizCode.SECKILL_REPEATED);
                    }

                    // 5. Lua 脚本原子减库存
                    String luaScript =
                            "local stock = redis.call('get', KEYS[1]) " +
                            "if not stock then return -1 end " +
                            "if tonumber(stock) < tonumber(ARGV[1]) then return -2 end " +
                            "redis.call('decrby', KEYS[1], ARGV[1]) " +
                            "return redis.call('get', KEYS[1])";

                    DefaultRedisScript<Long> redisScript = new DefaultRedisScript<>();
                    redisScript.setScriptText(luaScript);
                    redisScript.setResultType(Long.class);

redisScript.setScriptText(luaScript);
                    redisScript.setResultType(Long.class);

                    String stockKey = SECKILL_STOCK_KEY_PREFIX + killId;
                    Long result = stringRedisTemplate.execute(
                            redisScript,
                            Collections.singletonList(stockKey),
                            String.valueOf(num)
                    );

                    if (result == null || result == -1) {
                        throw new GulimallException(BizCode.SECKILL_OVER);
                    }
                    if (result == -2) {
                        throw new GulimallException(10001, "库存不足");
                    }

                    // 6. 生成订单号
                    String orderSn = generateOrderSn();

                    // 7. 发送订单消息到 RabbitMQ
                    Map<String, Object> orderMessage = new HashMap<>();
                    orderMessage.put("orderSn", orderSn);
                    orderMessage.put("skuId", skuId);
                    orderMessage.put("num", num);
                    orderMessage.put("seckillPrice", skuVo.getSeckillPrice().toString());
                    orderMessage.put("userId", userId);
                    orderMessage.put("killId", killId);
                    orderMessage.put("skuName", skuVo.getSkuName());
                    orderMessage.put("skuPrice", skuVo.getSkuPrice().toString());

orderMessage.put("skuPrice", skuVo.getSkuPrice().toString());

                    rabbitTemplate.convertAndSend(
                            MyRabbitConfig.SECKILL_ORDER_EXCHANGE,
                            MyRabbitConfig.SECKILL_ORDER_ROUTING_KEY,
                            orderMessage
                    );

                    // 8. 标记已秒杀（防重复）
                    stringRedisTemplate.opsForValue()
                            .set(userKey, "1", 24, TimeUnit.HOURS);

                    log.info("秒杀成功，订单号：{}, SKU：{}, 数量：{}", orderSn, skuId, num);
                    return orderSn;

                } finally {
                    lock.unlock();
                }
            } else {
                throw new GulimallException(10002, "抢购人数过多，请稍后再试");
            }
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new GulimallException(10000, "系统繁忙，请稍后再试");
        }
    }

    /**
