package com.atguigu.gulimall.thirdparty.service.impl;

import com.aliyun.oss.OSS;
import com.aliyun.oss.common.utils.BinaryUtil;
import com.aliyun.oss.model.MatchMode;
import com.aliyun.oss.model.PolicyConditions;
import com.atguigu.gulimall.common.exception.GulimallException;
import com.atguigu.gulimall.common.utils.BizCode;
import com.atguigu.gulimall.thirdparty.service.OssService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import java.nio.charset.StandardCharsets;
import java.text.SimpleDateFormat;
import java.util.Date;
import java.util.LinkedHashMap;
import java.util.Map;

@Service
public class OssServiceImpl implements OssService {

    @Autowired
    private OSS ossClient;

    @Value("${alibaba.cloud.access-key}")
    private String accessKey;

    @Value("${alibaba.cloud.oss.endpoint}")
    private String endpoint;

    @Value("${alibaba.cloud.oss.bucket}")
    private String bucket;

    /** 签名有效期: 30 秒 */
    private static final long EXPIRE_SECONDS = 30;

    /** 上传文件最大大小: 10 MB */
    private static final long MAX_FILE_SIZE = 10 * 1024 * 1024;

    @Override
    public Map<String, String> policy() {
        try {
            // 上传目录，按日期分片，格式: yyyy-MM-dd
            String dir = new SimpleDateFormat("yyyy-MM-dd").format(new Date()) + "/";

try {
            // 上传目录，按日期分片，格式: yyyy-MM-dd
            String dir = new SimpleDateFormat("yyyy-MM-dd").format(new Date()) + "/";

            // 签名过期时间
            Date expiration = new Date(System.currentTimeMillis() + EXPIRE_SECONDS * 1000);

            PolicyConditions policyConds = new PolicyConditions();
            policyConds.addConditionItem(PolicyConditions.COND_CONTENT_LENGTH_RANGE, 0, MAX_FILE_SIZE);
            policyConds.addConditionItem(MatchMode.StartWith, PolicyConditions.COND_KEY, dir);

            String postPolicy = ossClient.generatePostPolicy(expiration, policyConds);
            byte[] binaryData = postPolicy.getBytes(StandardCharsets.UTF_8);
            String encodedPolicy = BinaryUtil.toBase64String(binaryData);
            String postSignature = ossClient.calculatePostSignature(postPolicy);

            // OSS 公网访问 host
            String host = "https://" + bucket + "." + endpoint;

            Map<String, String> result = new LinkedHashMap<>();
            result.put("accessId", accessKey);
            result.put("policy", encodedPolicy);
            result.put("signature", postSignature);
            result.put("dir", dir);
            result.put("host", host);
            result.put("expire", String.valueOf(expiration.getTime() / 1000));

result.put("host", host);
            result.put("expire", String.valueOf(expiration.getTime() / 1000));

            return result;
        } catch (Exception e) {
            throw new GulimallException(BizCode.UNKNOWN_EXCEPTION.getCode(),
                    "OSS 签名生成失败: " + e.getMessage());
        }
    }
}

