                          @Value("${alibaba.cloud.sms.sign-name:}") String signName,

@Value("${alibaba.cloud.sms.sign-name:}") String signName,
                          @Value("${alibaba.cloud.sms.template-code:}") String templateCode,
                          ObjectMapper objectMapper) {
        this.accessKey = accessKey;
        this.secretKey = secretKey;
        this.region = region;
        this.signName = signName;
        this.templateCode = templateCode;
        this.objectMapper = objectMapper;
    }

    @Override
    public void sendVerificationCode(String phone, String code) {
        if (!StringUtils.hasText(accessKey) || !StringUtils.hasText(secretKey)
                || !StringUtils.hasText(signName) || !StringUtils.hasText(templateCode)) {
            throw new GulimallException(BizCode.UNKNOWN_EXCEPTION.getCode(), "短信服务未配置");
        }
        try {
            DefaultProfile profile = DefaultProfile.getProfile(region, accessKey, secretKey);
            IAcsClient client = new DefaultAcsClient(profile);
            CommonRequest request = new CommonRequest();
            request.setSysMethod(MethodType.POST);
            request.setSysDomain("dysmsapi.aliyuncs.com");
            request.setSysVersion("2017-05-25");
            request.setSysAction("SendSms");
            request.putQueryParameter("PhoneNumbers", phone);
            request.putQueryParameter("SignName", signName);
            request.putQueryParameter("TemplateCode", templateCode);

request.putQueryParameter("SignName", signName);
            request.putQueryParameter("TemplateCode", templateCode);
            request.putQueryParameter("TemplateParam", "{\"code\":\"" + code + "\"}");
            CommonResponse response = client.getCommonResponse(request);
            JsonNode result = objectMapper.readTree(response.getData());
            if (!"OK".equals(result.path("Code").asText())) {
                throw new GulimallException(BizCode.UNKNOWN_EXCEPTION.getCode(),
                        result.path("Message").asText("短信发送失败"));
            }
        } catch (GulimallException e) {
            throw e;
        } catch (Exception e) {
            throw new GulimallException(BizCode.UNKNOWN_EXCEPTION.getCode(), "短信发送失败");
        }
    }
}

