    private static final int TASK_LOCKED = 1;
    private static final int TASK_UNLOCKED = 2;
    private static final int TASK_DEDUCTED = 3;
    private static final int DETAIL_LOCKED = 1;
    private static final int DETAIL_UNLOCKED = 2;
    private static final int DETAIL_DEDUCTED = 3;

    private final WareOrderTaskService taskService;
