    @Override
    @Transactional
    public void lockOrderStock(WareSkuLockTo lockTo) {
        validate(lockTo);
        WareOrderTaskEntity existing = taskService.getOne(new LambdaQueryWrapper<WareOrderTaskEntity>()
                .eq(WareOrderTaskEntity::getOrderSn, lockTo.getOrderSn()), false);
        if (existing != null) {
            if (Integer.valueOf(TASK_LOCKED).equals(existing.getTaskStatus())) {
                return;
            }
            throw new GulimallException(BizCode.WARE_NO_STOCK.getCode(), "订单库存已释放，不能重复锁定");
        }

        WareOrderTaskEntity task = new WareOrderTaskEntity();
        task.setOrderId(lockTo.getOrderId());
        task.setOrderSn(lockTo.getOrderSn());
        task.setConsignee(lockTo.getConsignee());
        task.setConsigneeTel(lockTo.getConsigneeTel());
        task.setDeliveryAddress(lockTo.getDeliveryAddress());
        task.setOrderComment(lockTo.getOrderComment());
        task.setPaymentWay(lockTo.getPaymentWay());
        task.setTaskStatus(TASK_LOCKED);
        taskService.save(task);

task.setPaymentWay(lockTo.getPaymentWay());
        task.setTaskStatus(TASK_LOCKED);
        taskService.save(task);

        List<WareOrderTaskDetailEntity> details = new ArrayList<>();
        for (WareSkuLockTo.Item item : lockTo.getItems()) {
            lockItem(task.getId(), item, details);
        }
        taskDetailService.saveBatch(details);
        Long firstWareId = details.get(0).getWareId();
        if (details.stream().allMatch(detail -> firstWareId.equals(detail.getWareId()))) {
            task.setWareId(firstWareId);
            taskService.updateById(task);
        }
    }

    private void lockItem(Long taskId, WareSkuLockTo.Item item,
                          List<WareOrderTaskDetailEntity> details) {
        int remaining = item.getQuantity();
        List<WareSkuEntity> stocks = list(new LambdaQueryWrapper<WareSkuEntity>()
                .eq(WareSkuEntity::getSkuId, item.getSkuId()))
                .stream()
                .filter(stock -> available(stock) > 0)
                .sorted(Comparator.comparingInt(this::available).reversed())
                .toList();

.sorted(Comparator.comparingInt(this::available).reversed())
                .toList();

        for (WareSkuEntity stock : stocks) {
            if (remaining == 0) {
                break;
            }
            int quantity = Math.min(remaining, available(stock));
            if (baseMapper.lockStock(stock.getId(), quantity) != 1) {
                continue;
            }
            WareOrderTaskDetailEntity detail = new WareOrderTaskDetailEntity();
            detail.setTaskId(taskId);
            detail.setSkuId(item.getSkuId());
            detail.setSkuName(item.getSkuName());
            detail.setSkuNum(quantity);
            detail.setWareId(stock.getWareId());
            detail.setLockStatus(DETAIL_LOCKED);
            details.add(detail);
            remaining -= quantity;
        }
        if (remaining > 0) {
            throw new GulimallException(BizCode.WARE_NO_STOCK);
        }
    }

    @Override
    @Transactional
    public void unlockOrderStock(String orderSn) {
        if (orderSn == null || orderSn.isBlank()) {
            throw new GulimallException(BizCode.PARAM_VALID_EXCEPTION);
        }
        WareOrderTaskEntity task = taskService.getOne(new LambdaQueryWrapper<WareOrderTaskEntity>()
                .eq(WareOrderTaskEntity::getOrderSn, orderSn), false);
        if (task == null || Integer.valueOf(TASK_UNLOCKED).equals(task.getTaskStatus())) {
            return;
        }

if (task == null || Integer.valueOf(TASK_UNLOCKED).equals(task.getTaskStatus())) {
            return;
        }

        List<WareOrderTaskDetailEntity> details = taskDetailService.list(
                new LambdaQueryWrapper<WareOrderTaskDetailEntity>()
                        .eq(WareOrderTaskDetailEntity::getTaskId, task.getId())
                        .eq(WareOrderTaskDetailEntity::getLockStatus, DETAIL_LOCKED));
        for (WareOrderTaskDetailEntity detail : details) {
            if (baseMapper.unlockStock(findStockId(detail), detail.getSkuNum()) != 1) {
                throw new GulimallException(BizCode.UNKNOWN_EXCEPTION.getCode(), "库存解锁失败");
            }
            detail.setLockStatus(DETAIL_UNLOCKED);
        }
        if (!details.isEmpty()) {
            taskDetailService.updateBatchById(details);
        }
        task.setTaskStatus(TASK_UNLOCKED);
        taskService.updateById(task);
    }

