        this.sysMenuService = sysMenuService;
    }

    @GetMapping("/list")
    public R<?> list() {
        List<SysMenuEntity> menuTree = sysMenuService.listWithTree();
        return R.ok(menuTree);
    }

    @GetMapping("/nav")
    public R<?> nav(@RequestAttribute(value = "userId", required = false) Long userId) {
        if (userId == null) {
            Object principal = org.springframework.security.core.context.SecurityContextHolder
                    .getContext().getAuthentication().getPrincipal();
            if (principal instanceof Long) {
                userId = (Long) principal;
            }
        }

        if (userId == null) {
            return R.error(400, "用户未登录");
        }

userId = (Long) principal;
            }
        }

        if (userId == null) {
            return R.error(400, "用户未登录");
        }

        List<SysMenuEntity> menuList = sysMenuService.queryListByUserId(userId);
        // Filter to only directories and menus, not buttons
        List<SysMenuEntity> navMenus = menuList.stream()
                .filter(m -> m.getType() != 2)
                .toList();
        List<SysMenuEntity> menuTree = sysMenuService.buildTree(navMenus, 0L);
        return R.ok(menuTree);
    }

    @PostMapping("/save")
    public R<?> save(@RequestBody SysMenuEntity menu) {
        sysMenuService.save(menu);
        return R.ok();
    }

    @PutMapping("/update")
    public R<?> update(@RequestBody SysMenuEntity menu) {
        sysMenuService.updateById(menu);
        return R.ok();
    }

    @DeleteMapping("/delete/{menuId}")
    public R<?> delete(@PathVariable Long menuId) {
        List<Long> ids = new ArrayList<>();
        collectMenuIds(menuId, ids);
        sysMenuService.removeByIds(ids);
        return R.ok();
    }

    private void collectMenuIds(Long parentId, List<Long> ids) {
        ids.add(parentId);
        sysMenuService.list(new LambdaQueryWrapper<SysMenuEntity>()
                        .eq(SysMenuEntity::getParentId, parentId))
                .forEach(child -> collectMenuIds(child.getMenuId(), ids));
    }
