                     @RequestParam(defaultValue = "10") long limit,
                     @RequestParam(required = false) String username) {
        LambdaQueryWrapper<SysUserEntity> wrapper = new LambdaQueryWrapper<>();
        if (StringUtils.hasText(username)) {
            wrapper.like(SysUserEntity::getUsername, username);
        }
        wrapper.orderByDesc(SysUserEntity::getCreateTime);

        IPage<SysUserEntity> result = sysUserService.page(new Page<>(page, limit), wrapper);
        return R.ok(result);
    }

    @PostMapping("/save")
    public R<?> save(@RequestBody SysUserEntity user) {
        // Check duplicate username
        SysUserEntity existing = sysUserService.queryByUsername(user.getUsername());
