import com.atguigu.gulimall.admin.sys.entity.SysMenuEntity;
import com.atguigu.gulimall.admin.sys.service.SysMenuService;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;
import com.baomidou.mybatisplus.extension.service.impl.ServiceImpl;
import org.springframework.stereotype.Service;

import java.util.*;
import java.util.stream.Collectors;

@Service
public class SysMenuServiceImpl extends ServiceImpl<SysMenuDao, SysMenuEntity> implements SysMenuService {

    private final SysUserDao sysUserDao;

    public SysMenuServiceImpl(SysUserDao sysUserDao) {
        this.sysUserDao = sysUserDao;
    }

    @Override
    public List<SysMenuEntity> queryListByUserId(Long userId) {
        // Admin user (userId == 1) gets all menus
        if (userId == 1) {
            return list(new LambdaQueryWrapper<SysMenuEntity>()
                    .orderByAsc(SysMenuEntity::getOrderNum));
        }

        List<Long> menuIdList = sysUserDao.queryAllMenuId(userId);
        if (menuIdList.isEmpty()) {
            return Collections.emptyList();
        }
        return list(new LambdaQueryWrapper<SysMenuEntity>()
                .in(SysMenuEntity::getMenuId, menuIdList)
                .orderByAsc(SysMenuEntity::getOrderNum));
    }

    @Override

.in(SysMenuEntity::getMenuId, menuIdList)
                .orderByAsc(SysMenuEntity::getOrderNum));
    }

    @Override
    public List<SysMenuEntity> listWithTree() {
        List<SysMenuEntity> allMenus = list(new LambdaQueryWrapper<SysMenuEntity>()
                .orderByAsc(SysMenuEntity::getOrderNum));

        return buildTree(allMenus, 0L);
    }

    public List<SysMenuEntity> buildTree(List<SysMenuEntity> menus, Long parentId) {
        return menus.stream()
                .filter(menu -> parentId.equals(menu.getParentId()) || (menu.getParentId() == null && parentId == 0L))
                .peek(menu -> menu.setChildren(buildTree(menus, menu.getMenuId())))
                .collect(Collectors.toList());
    }
}

